using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;
public static class BuildBatchTen {
 static Material Mat(string name,Color c,bool metal){var m=new Material(Shader.Find("Standard"));m.name=name;var t=new Texture2D(64,64);for(int y=0;y<64;y++)for(int x=0;x<64;x++){float v=.8f+.3f*Mathf.PerlinNoise(x*.3f,y*.06f);t.SetPixel(x,y,c*v);}t.Apply();AssetDatabase.CreateAsset(t,"Assets/Generated/"+name+"Tex.asset");m.mainTexture=t;m.SetFloat("_Metallic",metal?.7f:0);m.SetFloat("_Glossiness",metal?.45f:.18f);AssetDatabase.CreateAsset(m,"Assets/Generated/"+name+".mat");return m;}
 static void Part(GameObject root,string name,Vector3 p,Vector3 scale,Material m,Vector3 rotation){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(root.transform,false);g.transform.localPosition=p;g.transform.localScale=scale;g.transform.localEulerAngles=rotation;g.GetComponent<Renderer>().sharedMaterial=m;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());}
 public static void Run(){try{Directory.CreateDirectory("Assets/Generated");Directory.CreateDirectory("../Bundle");Directory.CreateDirectory("../Preview");var wood=Mat("AshWood",new Color(.38f,.21f,.09f),false);var steel=Mat("WornSteel",new Color(.55f,.60f,.63f),true);var leather=Mat("Leather",new Color(.18f,.10f,.055f),false);var root=new GameObject("delveHarvestScythe");
  Part(root,"BentAshShaft",new Vector3(0,.18f,0),new Vector3(.045f,1.35f,.045f),wood,new Vector3(0,0,-6));
  Part(root,"Grip",Vector3.zero,new Vector3(.06f,.20f,.06f),leather,Vector3.zero);Part(root,"SideHandle",new Vector3(.12f,.37f,0),new Vector3(.25f,.045f,.045f),wood,new Vector3(0,0,12));
  var verts=new System.Collections.Generic.List<Vector3>();var triangles=new System.Collections.Generic.List<int>();for(int i=0;i<=16;i++){float t=i/16f;float x=.07f-.95f*t,y=.85f+.28f*Mathf.Sin(t*1.8f),width=.14f*(1-t)+.008f;verts.Add(new Vector3(x,y,-.012f));verts.Add(new Vector3(x,y-width,-.012f));verts.Add(new Vector3(x,y,.012f));verts.Add(new Vector3(x,y-width,.012f));if(i>0){int k=i*4;triangles.AddRange(new[]{k-4,k-3,k,k-3,k+1,k,k-2,k+2,k-1,k-1,k+2,k+3,k-4,k,k-2,k-2,k,k+2,k-3,k-1,k+1,k+1,k-1,k+3});}}
  var mesh=new Mesh();mesh.SetVertices(verts);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,"Assets/Generated/ScytheBlade.asset");var blade=new GameObject("CurvedBlade");blade.transform.SetParent(root.transform,false);blade.AddComponent<MeshFilter>().sharedMesh=mesh;blade.AddComponent<MeshRenderer>().sharedMaterial=steel;Part(root,"BladeSocket",new Vector3(.075f,.8f,0),new Vector3(.07f,.18f,.065f),steel,Vector3.zero);
  string prefab="Assets/Generated/delveHarvestScythe.prefab";PrefabUtility.SaveAsPrefabAsset(root,prefab);AssetDatabase.SaveAssets();RenderSettings.ambientLight=Color.gray;var light=new GameObject("Key").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.4f;light.transform.rotation=Quaternion.Euler(35,-20,0);var cam=new GameObject("Camera").AddComponent<Camera>();cam.orthographic=true;cam.orthographicSize=.95f;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.clear;cam.transform.position=new Vector3(1,1.2f,-4);cam.transform.LookAt(new Vector3(-.3f,.35f,0));var rt=new RenderTexture(512,512,24);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var image=new Texture2D(512,512,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,512,512),0,0);image.Apply();File.WriteAllBytes("../Preview/delveHarvestScythe.png",image.EncodeToPNG());
  var build=new AssetBundleBuild{assetBundleName="batchten.unity3d",assetNames=new[]{prefab},addressableNames=new[]{"delveHarvestScythe"}};if(BuildPipeline.BuildAssetBundles("../Bundle",new[]{build},BuildAssetBundleOptions.ChunkBasedCompression,BuildTarget.StandaloneWindows64)==null)throw new Exception("Bundle failed");File.WriteAllText("../result.txt","PASS custom curved scythe, textured shaft and steel blade, rendered inventory icon");EditorApplication.Exit(0);
 }catch(Exception e){Debug.LogException(e);File.WriteAllText("../result.txt","FAIL "+e);EditorApplication.Exit(1);}}
}
